    success: bool
    message: str


def _qmd_env(qmd_dir: Path) -> dict[str, str]:
    return {
        **os.environ,
        "QMD_CONFIG_DIR": str(qmd_dir),
        "INDEX_PATH": str(qmd_dir / "index.sqlite"),
    }


