    if mode not in SEARCH_MODES:
        raise ValueError(f"unknown qmd mode: {mode}")
    if shutil.which("qmd") is None:
        return []
    try:
        result = subprocess.run(
            ["qmd", mode, query, "--json", "-n", str(limit)],
            capture_output=True,
            text=True,
            timeout=120,
            cwd=root,
            env=_qmd_env(qmd_dir),
        )
