def test_plan_default_collections_only_existing_schema_dirs(tmp_path: Path):
    (tmp_path / "concepts").mkdir()
    (tmp_path / "people").mkdir()
    (tmp_path / "sources").mkdir()
    # "meetings" and "journal" etc. deliberately absent.

    plans = qmd_service.plan_default_collections(_config(tmp_path))
    names = {plan.name for plan in plans}
    assert names == {"concepts", "people", "sources"}
    for plan in plans:
        assert plan.pattern == "**/*.md"


def test_plan_default_collections_skips_already_registered(tmp_path: Path):
    (tmp_path / "concepts").mkdir()
    (tmp_path / "people").mkdir()

    qmd_dir = tmp_path / ".wakil" / "qmd"
    qmd_dir.mkdir(parents=True)
    (qmd_dir / "index.yml").write_text(
        f"collections:\n  concepts:\n    path: {tmp_path / 'concepts'}\n    pattern: '**/*.md'\n"
    )

    plans = qmd_service.plan_default_collections(_config(tmp_path))
    assert {plan.name for plan in plans} == {"people"}


def test_plan_default_collections_includes_ingest_and_generated_dirs(tmp_path: Path):
    (tmp_path / "sources").mkdir()
    (tmp_path / "drafts").mkdir()

    plans = qmd_service.plan_default_collections(_config(tmp_path))
    names = {plan.name for plan in plans}
    assert "sources" in names
    assert "drafts" in names


def test_plan_default_collections_flattens_nested_schema_dir(tmp_path: Path):
    (tmp_path / "ideas" / "reflections").mkdir(parents=True)

